class Solution:
    def lengthLongestPath(self, input: str) -> int:
        prefixes = {0: 0}
        best = 0
        for entry in input.split('\n'):
            name = entry.lstrip('\t')
            depth = len(entry) - len(name)
            length = prefixes[depth] + len(name)
            if '.' in name:
                best = max(best, length)
            else:
                prefixes[depth + 1] = length + 1
        return best
